/* ============================ ROLES ============================ */
const ROLES={
  owner:  {label:'Owner',        desc:'Everything, including profit, quotes, team and settings'},
  planner:{label:'Event planner',desc:'Runs events end to end: quotes, client money, vendors, approvals, tasks, crew. Profit and pricing visible unless switched off'},
  manager:{label:'Manager',      desc:'Vendors, payments, tasks, crew, expenses, issues. No client pricing or profit'},
  staff:  {label:'Staff',        desc:'Today view, own tasks, run sheet, expense capture. Sees vendor names and scope, not amounts'}
};
const CAPS={
  owner:['*'],
  planner:['events.edit','stage','vendors','vendors.amounts','payments','changes','changes.cost','tasks.manage','crew.manage','crew.assign','budget.view','expenses','reimb.settle','float.issue','runsheet','directory.edit','issues','activity','docs.view','docs.edit','export'],
  manager:['events.edit','vendors','vendors.amounts','payments','changes.cost','tasks.manage','crew.assign','budget.view','expenses','runsheet','directory.edit','issues','activity','docs.view'],
  staff:['tasks.own','expenses','issues','docs.view']
};
/* Capability = what a person may SEE or DO. 'profit','client','quote','budget','changes','approve','docs.confidential' require pricing visibility (owner, or planner with profit on). The same check gates tabs, modals, copied text and notifications. */
function can(cap){const u=me();if(!u)return false;if(u.role==='owner')return true;if(['profit','client','quote','budget','changes','approve','docs.confidential','client.pricing'].includes(cap))return u.role==='planner'&&u.profit!==false;return (CAPS[u.role]||[]).includes(cap)}
const seesMoney=()=>can('vendors.amounts');

/* ============================ STAGES ============================ */
const STAGES=['enquiry','quoted','confirmed','planning','eventweek','done','closed'];
const STAGE={enquiry:'Enquiry',quoted:'Quoted',confirmed:'Confirmed',planning:'Planning',eventweek:'Event week',done:'Event over',closed:'Closed',lost:'Lost',cancelled:'Cancelled'};
const STAGE_HELP={enquiry:'Someone asked. Capture what they want, then build a quote.',quoted:'The client has the quote. Chase it; when they say yes, confirm.',confirmed:'Contract, budget baseline and payment plan are set. Book vendors.',planning:'Vendors, tasks, crew and the run sheet come together here.',eventweek:'Final confirmations. The run sheet goes live on the day.',done:'The event happened. Collect, pay, settle, then close.',closed:'Figures are locked. This is the final margin.',lost:'Did not convert. Kept for the record; never counted.',cancelled:'Cancelled after confirmation. Cancellation charge, forfeited advances and refunds are the final figures.'};
const stageIdx=s=>s==='lost'?-1:s==='cancelled'?6:STAGES.indexOf(s);
const isLive=e=>stageIdx(e.stage)>=2&&e.stage!=='closed'&&e.stage!=='cancelled';
const locked=e=>e.stage==='closed'||e.stage==='lost'||e.stage==='cancelled';
const counts=e=>stageIdx(e.stage)>=2&&!e.history&&e.stage!=='lost';

