const uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36).slice(-4);
const nowISO=()=>new Date().toISOString();
const todayStr=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const nowHM=()=>{const d=new Date();return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
let saveFailed=false;function save(){try{localStorage.setItem(KEY,JSON.stringify(S));if(saveFailed){saveFailed=false;const b=document.getElementById('savebar');if(b)b.remove()}return true}catch(e){saveFailed=true;let b=document.getElementById('savebar');if(!b){b=document.createElement('div');b.id='savebar';b.className='alert';b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:70;border-radius:0';b.innerHTML='<b>Not saved.</b> This device\'s storage is full or blocked. Your last change is on screen only. Take a backup now (Settings → Backup) and remove large documents.';(document.getElementById('device')||document.body).appendChild(b)}return false}}
function load(){try{const r=localStorage.getItem(KEY);if(r){S=JSON.parse(r);if(S&&S.v===510)return}}catch(e){}S=seed();save()}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function inr(p){const neg=p<0;let r=Math.floor(Math.abs(Math.round(p))/100);let s=String(r);let last=s.slice(-3),rest=s.slice(0,-3);if(rest)last=','+last;rest=rest.replace(/\B(?=(\d{2})+(?!\d))/g,',');return (neg?'−':'')+'₹'+rest+last}
function toPaise(v){const n=parseFloat(String(v).replace(/[^\d.\-]/g,''));return isNaN(n)?null:Math.round(n*100)}
function pct(a,b){return b>0?((a/b)*100).toFixed(1)+'%':'—'}
function fmtDate(d){if(!d)return'';const x=new Date(d+(d.length===10?'T00:00:00':''));return x.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}
function fmtShort(d){if(!d)return'';return new Date(d+'T00:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short'})}
function fmtTs(iso){const x=new Date(iso);return x.toLocaleDateString('en-IN',{day:'numeric',month:'short'})+', '+x.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}
function addDays(d,n){const x=new Date(d+'T00:00:00');x.setDate(x.getDate()+n);return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')}
function daysUntil(d){return Math.round((new Date(d+'T00:00:00')-new Date(todayStr()+'T00:00:00'))/864e5)}

