const payComms=eid=>agreedComms(eid).filter(c=>!c.clientPays);
const costComms=eid=>payComms(eid).filter(c=>!c.deposit);
const linkedChangeCost=cid=>{const cm=S.commitments.find(c=>c.id===cid);if(!cm||cm.fromChangeId)return 0;return sum(live(S.changes).filter(ch=>chApproved(ch)&&ch.commitmentId===cid&&!ch.generatedCommitmentId),ch=>ch.costPaise)};
const feeOf=(e,costs)=>e.pricing==='costplus'?(e.feeType==='flat'?(e.feeFlatPaise||0):Math.round(costs*(e.feePct||0)/100)):0;
const paysFor=cid=>live(S.payments).filter(p=>p.commitmentId===cid);
const sum=(a,f)=>a.reduce((t,x)=>t+(f?f(x):x),0);
const daysBetween=(a,b)=>Math.max(1,Math.round((new Date(b+'T00:00:00')-new Date(a+'T00:00:00'))/864e5)+1);
const attDays=a=>a.days?Object.keys(a.days).filter(d=>a.days[d]==='present'||a.days[d]===true).length:null;
let asgCost=a=>a.ratePaise*(a.attendanceFinal?(attDays(a)||0):daysBetween(a.from,a.to));
