/* ---- TAX: one model everywhere. Every client-side amount is NET (ex-tax) in storage; GROSS = net + tax under the event's frozen tax terms. Milestones, invoices, receipts and credit notes are GROSS (what moves). Profit is always ex-tax. ---- */
const taxTermsOf=e=>e.tax||{on:!!(e.gstOn&&S.company.gstOn),pct:S.company.gstPct||18,mode:S.company.gstMode||'on_top',igst:(()=>{const cl=S.clients.find(c=>c.id===e.clientId);return !!(cl&&cl.state&&S.company.state&&cl.state.toLowerCase()!==S.company.state.toLowerCase())})()};
const taxOn=(e,net)=>{const t=taxTermsOf(e);return t.on?Math.round(net*t.pct/100):0};
const grossOf=(e,net)=>net+taxOn(e,net);
const netOfGross=(e,gross)=>{const t=taxTermsOf(e);return t.on?Math.round(gross/(1+t.pct/100)):gross};
const quoteTotals=e=>{const ls=(e.quote&&e.quote.lines)||[];const cost=sum(ls,l=>l.qty*l.unitCostPaise);const disc=(e.quote&&e.quote.discountPaise)||0;const t=taxTermsOf(e);let entered=e.pricing==='costplus'?cost+feeOf(e,cost):sum(ls,l=>l.qty*l.unitPricePaise)-disc;const net=t.mode==='inclusive'?netOfGross(e,entered):entered;const gst=taxOn(e,net);return {cost,net,gst,gross:net+gst,discount:disc,margin:net-cost,price:net,total:net+gst,lines:ls,entered}};
const clientTotal=e=>grossOf(e,calc(e).contract);
