document.addEventListener('change',evt=>{const el=evt.target.closest('[data-act]');if(evt.target.id==='docfile'){addDocs(evt.target.files);return}if(window.ACTS_FILE&&evt.target.dataset.file&&ACTS_FILE[evt.target.dataset.file]){return ACTS_FILE[evt.target.dataset.file](evt.target)}if(!el)return;const a=el.dataset.act;if(window.ACTS_CHANGE&&ACTS_CHANGE[a])return ACTS_CHANGE[a](el,evt);if(a==='year'){S.ui.year=el.value;save();render()}if(a==='cv-event'){S.ui.cvEvent=el.value;save();render()}if(a==='esort'){S.ui.esort=el.value;save();render()}if(a==='jc-event'){S.ui.jcEvent=el.value;S.ui.jcComm=null;save();render()}if(a==='jc-comm'){S.ui.jcComm=el.value;save();render()}});
document.addEventListener('input',evt=>{const el=evt.target.closest('[data-act]');if(!el)return;const a=el.dataset.act;if(window.ACTS_INPUT&&ACTS_INPUT[a])return ACTS_INPUT[a](el,evt);if(a==='vq'||a==='vmin'||a==='eq'||a==='cq'){S.ui[a]=el.value;save();const pos=el.selectionStart;render();const n=F(el.id);if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}}});
